       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       line-height: 1.5;
     }

     main {
       width: min(100%, 30rem);
     }

     .card {
       padding: 2rem;
       border: 1px solid rgba(216, 224, 236, 0.9);
       border-radius: 1.5rem;
       background: rgba(255, 255, 255, 0.92);
       box-shadow: 0 1.5rem 4rem rgba(21, 32, 51, 0.12);
       backdrop-filter: blur(16px);
     }

     h1 {
       margin: 0 0 0.5rem;
       font-size: clamp(1.8rem, 5vw, 2.25rem);
       line-height: 1.1;
       letter-spacing: -0.04em;
     }

     .intro {
       margin: 0 0 1.75rem;
       color: var(--muted);
     }

     .form-field {
       display: grid;
       grid-template-columns: auto 1fr;
       gap: 0.75rem;
       align-items: start;
       padding: 1rem;
       border: 1px solid var(--border);
       border-radius: 1rem;
       background: #f8fafc;
     }

     input[type="checkbox"] {
       width: 1.25rem;
       height: 1.25rem;
       margin: 0.15rem 0 0;
       accent-color: var(--primary);
       cursor: pointer;
     }

     input[type="checkbox"]:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     label {
       font-weight: 700;
       cursor: pointer;
     }

     .helper-text {
       grid-column: 2;
       margin: -0.35rem 0 0;
       color: var(--muted);
       font-size: 0.95rem;
     }

     button {
       width: 100%;
       margin-top: 1.25rem;
       padding: 0.9rem 1.25rem;
       border: 0;
       border-radius: 999px;
       background: var(--primary);
       color: #ffffff;
       font: inherit;
       font-weight: 800;
       cursor: pointer;
       box-shadow: 0 0.75rem 1.5rem rgba(37, 99, 235, 0.24);
       transition: background-color 160ms ease, transform 160ms ease, box-shadow 160ms ease;
     }

     button:hover {
       background: var(--primary-dark);
       box-shadow: 0 1rem 1.75rem rgba(37, 99, 235, 0.28);
       transform: translateY(-1px);
     }

     button:focus-visible {
       outline: 3px solid var(--focus);
       outline-offset: 3px;
     }

     .status {
       min-height: 1.5rem;
       margin: 1rem 0 0;
       color: var(--success-text);
       font-weight: 700;
     }

     .status:not(:empty) {
       padding: 0.75rem 1rem;
       border-radius: 0.75rem;
       background: var(--success-bg);
     }
   </style>
 </head>
 <body>
   <main>
     <section class="card" aria-labelledby="form-title">
       <h1 id="form-title">Confirm your consent</h1>
       <p class="intro">Please review and accept the terms before continuing.</p>

       <form id="consent-form">
         <div class="form-field">
           <input type="checkbox" id="terms" name="terms" required aria-describedby="terms-helper">
           <label for="terms">I agree to the terms of use</label>
           <p class="helper-text" id="terms-helper">Required to create or access your account.</p>
         </div>

         <button type="submit">Submit consent</button>
         <p class="status" id="form-status" role="status" aria-live="polite"></p>
       </form>
     </section>
   </main>

   <script>
     const form = document.querySelector("#consent-form");
     const status = document.querySelector("#form-status");

     form.addEventListener("submit", (event) => {
       event.preventDefault();

       if (!form.checkValidity()) {
         form.reportValidity();
         return;
       }

       status.textContent = "Thanks. Your consent has been submitted.";
     });
   </script>
 </body>
 </html>

